import{_ as r,o as a,c as e,ag as o}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"前言","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/preface.md","filePath":"science-log/src/preface.md"}'),n={name:"science-log/src/preface.md"};function s(d,t,l,i,h,c){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h1><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p><strong>科学日志（Science Log）</strong> 是一本持续更新的科学新闻深度解析书籍。每一天，科学界都在产出海量论文和新闻——但大部分报道停留在&quot;标题层&quot;：告诉你发现了什么，却不告诉你为什么、怎么发现的、底层机制是什么。</p><p>这本书的目标是<strong>逐层下钻</strong>：从新闻标题 → 研究背景 → 分子机制 → 物理定律 → 第一性原理。每一条新闻都是一次&quot;解剖学&quot;练习。</p><h2 id="三层次体系" tabindex="-1">三层次体系 <a class="header-anchor" href="#三层次体系" aria-label="Permalink to &quot;三层次体系&quot;">​</a></h2><p>每一期科学日报包含三个层次的内容：</p><table tabindex="0"><thead><tr><th>层次</th><th>定位</th><th>目标读者</th><th>典型深度</th></tr></thead><tbody><tr><td><strong>表层扩展</strong></td><td>扩大背景、补充数据、关联趋势</td><td>快速了解科学动态</td><td>~2000 字/条</td></tr><tr><td><strong>原始知识层</strong></td><td>拆解到分子机制、物理定律</td><td>理解科学原理</td><td>~5000 字/条</td></tr><tr><td><strong>交叉关联</strong></td><td>跨领域统一逻辑、与 AI 理论关联</td><td>发现深层规律</td><td>整期总结</td></tr></tbody></table><h2 id="内容来源" tabindex="-1">内容来源 <a class="header-anchor" href="#内容来源" aria-label="Permalink to &quot;内容来源&quot;">​</a></h2><ul><li><strong>科学日报</strong>：每日精选 10-20 条全球科学新闻，覆盖生物医学、太空物理、量子材料、AI 科技、能源环境</li><li><strong>科技周刊</strong>：阮一峰《科技爱好者周刊》的扩展分析，从科技现象到深层社会含义</li><li><strong>科学快报</strong>：每日自动生成的科学新闻简报，快速索引</li></ul><h2 id="阅读建议" tabindex="-1">阅读建议 <a class="header-anchor" href="#阅读建议" aria-label="Permalink to &quot;阅读建议&quot;">​</a></h2><ul><li><strong>按时间线阅读</strong>：每天一期，建立科学认知的连续性</li><li><strong>按主题阅读</strong>：通过搜索功能，追踪特定领域的进展</li><li><strong>按层次阅读</strong>：先看表层扩展了解&quot;是什么&quot;，再深入原始知识层理解&quot;为什么&quot;</li></ul><h2 id="为什么做这件事" tabindex="-1">为什么做这件事 <a class="header-anchor" href="#为什么做这件事" aria-label="Permalink to &quot;为什么做这件事&quot;">​</a></h2><p>2026 年，AI 正在改变科学研究的方式——但 AI 生成的内容往往停留在&quot;模式匹配&quot;层，缺乏对底层机制的真正理解。这本书的每一篇分析都坚持<strong>从第一性原理出发</strong>：不是告诉你&quot;研究发现了 X&quot;，而是告诉你&quot;X 是怎么被发现的、为什么 X 成立、X 在更大的知识框架中处于什么位置&quot;。</p><p>这是一种<strong>对抗 AI 时代认知退化的练习</strong>——在零摩擦生成内容的时代，坚持用摩擦换取真正的理解。</p><hr><p><em>本书由郝兴森（导演）与演员（AI 助手）协作完成。</em><em>更新频率：随科学日报/科技周刊同步更新。</em></p>',16)])])}const p=r(n,[["render",s]]);export{g as __pageData,p as default};
